I(P(56),"예상 오답 — $\\cos\\frac k2=0$인 갈래(π의 홀수배)를 빠뜨리거나 $\\tan s=\\frac{4s}\\pi$의 근을 구간마다 하나씩 세지 않은 경우",
 ["덧셈정리로 조건이 $\\frac{2\\sin k}k=2\\alpha\\cos k+\\beta$ 한 식, 두 진동수로 $\\alpha=\\frac2\\pi$, $\\beta=\\frac4\\pi$.",
  "반각으로 $\\cos\\frac k2\\left(\\frac4k\\sin\\frac k2-\\frac8\\pi\\cos\\frac k2\\right)=0$ — 두 갈래."],
 {'C2':("공식",r"$\int_t^{t+2}f=\alpha\{f(t)+f(t+2)\}+\beta f(t+1)$."),'C3':("좋은 함수",r"모든 $t$에서 성립."),'C4':("조건과 묻는 것",r"$\sin\frac\pi2x$, $\sin\pi x$가 좋은 함수; $\sin kx$가 좋은 $k<100$의 개수."),'C5':("근삿값",r"$3.14<\pi<3.15$.")},
 [("덧셈정리",[r"$\sin(u\pm k)$ 전개."]),("방정식의 근의 개수",[r"$\tan s$와 직선의 교점."])],
 [("의도",['C2']),("치환",['C2']),("계산",['C2']),("필요충분",['C3']),("$\\alpha$, $\\beta$",['C4']),("반각",['C4']),("두 갈래",['C4','C5']),("근의 개수",['C4']),("답",['C4','C5'])],
 [("$\\sin u=1$",'C3',[r"모든 $u$에서 성립 ⇔ 계수가 $0$."]),("겹침",'C4',[r"(ⅱ)의 근은 $\cos s\ne0$이라 (ⅰ)과 다름."])],
 [("변형 · $k<60$",[r"(같은 조건에서) 함수 $\sin kx$가 좋은 함수가 되도록 하는 $60$보다 작은 양수 $k$의 개수를 구하시오. (단, $3.14<\pi<3.15$이다.)"],20,r"홀수배 $1\pi\sim19\pi$의 $10$개 + $s<30$에서 $n=0\sim9$의 $10$개.")],
 "적분 공식의 정확성 → 계수 비교 + 반각 두 갈래.")

I(P(57),"예상 오답 — 두 정사영의 길이를 항상 더하거나 항상 겹친다고 보아 짧은 선분이 긴 선분 안에 들어가는 경우를 놓친 경우",
 ["수선의 발 좌표 $x\\cos\\theta+y\\sin\\theta$ → 두 정사영의 반길이 $\\frac{21}2c$, $\\frac{11}2c$, 중점 거리 $12\\sin\\theta$.",
  "포함·겹침·분리 세 경우, 경계 $\\tan\\theta=\\frac5{12}$, $\\frac43$."],
 {'C1':("도형",r"선분 $\mathrm{AB}$, $\mathrm{CD}$ (평행)."),'C2':("정사영",r"각 $\theta$인 직선 $l$ 위로 내린 수선의 발 전체."),'C3':("$w(\\theta)$",r"한 선분이면 길이, 두 선분이면 길이의 합."),'C4':("점",r"한 점은 길이 $0$."),
  'C5':("적분",r"$\int_0^\pi w\,d\theta$."),'C6':("묻는 것",r"그 값.")},
 [("정사영 좌표",[r"단위벡터와의 내적."]),("구간의 합집합",[r"중점 거리와 반길이 비교."])],
 [("의도",['C2']),("좌표",['C1','C2']),("세 경우",['C3']),("$w$",['C3','C4']),("대칭",['C5']),("앞 두 구간",['C5']),("마지막 구간",['C5']),("답",['C6'])],
 [("포함",'C3',[r"$12\sin\theta\le5c$이면 긴 선분 자신."]),("$\\theta=\\frac\\pi2$",'C4',[r"두 선분 모두 한 점."])],
 [("변형 · 다른 두 선분",[r"좌표평면 위의 네 점 $\mathrm A(0,0)$, $\mathrm B(25,0)$, $\mathrm C(9,12)$, $\mathrm D(16,12)$에 대하여 두 선분 $\mathrm{AB}$, $\mathrm{CD}$로 이루어진 도형을 $K$라 하자. (같은 방법으로) $w(\theta)$를 정할 때, $\int_0^\pi w(\theta)d\theta$의 값을 구하시오."],54,r"경계 $\tan\theta=\frac34$, $\frac43$; $2\left(15+\frac{16}5+\frac{12}5+\frac{32}5\right)$.")],
 "정사영의 합집합 → 포함·겹침·분리.")

I(P(58),"예상 오답 — 최우수 참가자가 반드시 누군가의 $1$위라는 사실을 놓쳐 $X=0$인데 최우수가 있는 경우를 센 경우",
 ["최우수 $W$를 두 상대보다 높게 둔 다수가 서로 겹침 → 겹친 심사위원은 $W$를 $1$위로.",
  "$X=1$: 나머지 두 사람이 $W$를 $2$위로 두되 아래 순서가 엇갈려야."],
 {'C1':("심사",r"$3$명이 $\mathrm A$, $\mathrm B$, $\mathrm C$ 순위."),'C2':("확률",r"$6$가지 중 균등, 독립."),'C3':("우세",r"$2$명 이상이 더 높게."),'C4':("$X$",r"최우수를 $1$위로 둔 심사위원 수, 없으면 $0$."),
  'C5':("묻는 것",r"$\mathrm V(X)=\frac qp$; $p+q$."),'C6':("서로소",r"기약분수.")},
 [("다수결",[r"콩도르세 승자."]),("비둘기집",[r"두 다수($2$명 이상)의 겹침."])],
 [("의도",['C4']),("전체",['C2']),("$1$위",['C3','C4']),("$X=3,2$",['C4']),("$X=1$",['C4']),("$X=0$",['C4']),("분포",['C4']),("답",['C5','C6'])],
 [("겹침",'C3',[r"$3$명 중 $2$명 + $2$명은 반드시 겹침."]),("순환",'C4',[r"$X=0$은 우세 관계가 순환하는 경우."])],
 [("변형 · 평균",[r"(같은 심사에서) $\mathrm E(X)=\frac qp$일 때, $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],17,r"$\frac16+\frac43+\frac13=\frac{11}6$.")],
 "다수결 우세 → 두 다수의 겹침.")

I(P(59),"예상 오답 — 장축이 항상 $x$축 방향이라고 보아 $h=9$만 찾고 (나)로 버리지 못한 경우",
 ["닮음으로 그림자 타원 $\\frac{(X-X_0)^2}{m^2}+\\frac{Y^2}{n^2}=1$, $m=\\frac{18}{h-6}$, $n^2=\\frac{9h}{h-6}$.",
  "$m$, $n$의 대소가 $h$에 따라 바뀜 → 초점 거리 $6$에서 $h=9$, $12$; (나)로 $h=12$."],
 {'C1':("고리",r"중심 $(6,0,3)$, 반지름 $3$, $yz$평면과 평행."),'C2':("그림자",r"$\mathrm L(0,0,h)$에서 비춘 $xy$평면 위의 점."),'C3':("타원",r"$C$는 타원."),
  'C4':("(가)",r"초점 거리 $6$."),'C5':("(나)",r"$x$좌표 최댓값 $\le12$."),'C6':("묻는 것",r"삼각형 $\mathrm{LF_1F_2}$의 넓이.")},
 [("중심사영",[r"$\mathrm{S}=\mathrm L+s(\mathrm R-\mathrm L)$."]),("삼수선의 정리",[r"$\mathrm{LM}\perp\mathrm F_1\mathrm F_2$."])],
 [("의도",['C3']),("$h>6$",['C2','C3']),("닮음",['C1','C2']),("방정식",['C2']),("타원",['C3']),("장축 방향",['C4']),("(나)",['C5']),("답",['C6'])],
 [("장축 방향",'C4',[r"$h=12$면 $n>m$ — 초점이 $y$방향."]),("$h\\le6$",'C3',[r"그림자가 한없이 멀어짐."])],
 [("변형 · (나) 최댓값 $>12$",[r"(같은 고리 $K$와 광원 $\mathrm L(0,0,h)$에 대하여) 그림자 $C$가 타원이고 (가) 두 초점 사이 거리가 $6$, (나) $C$ 위의 점의 $x$좌표의 최댓값이 $12$보다 크다. $C$의 두 초점을 $\mathrm F_1$, $\mathrm F_2$라 할 때 삼각형 $\mathrm{LF_1F_2}$의 넓이를 구하시오."],27,r"$h=9$: 초점 $(9,0,0)$, $(15,0,0)$, 높이 $9$.")],
 "그림자 타원의 장축 방향이 광원 높이로 바뀐다.")

I(P(60),"예상 오답 — 반지름의 비가 $\\mathrm P$에 따라 변한다고 보거나, $\\overline{\\mathrm{AP}}$가 같은 점이 두 개인 경우를 하나로 센 경우",
 ["보각의 사인이 같아 $R_1:R_2=\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AC}}=13:20$.",
  "$\\overline{\\mathrm O_1\\mathrm O_2}\\sin\\angle\\mathrm{APB}=\\frac12\\overline{\\mathrm{BC}}$ → $\\overline{\\mathrm O_1\\mathrm O_2}\\propto\\overline{\\mathrm{AP}}$."],
 {'C1':("점",r"변 $\mathrm{BC}$ 위의 $\mathrm P$."),'C2':("외접원",r"$\mathrm O_1$, $\mathrm O_2$."),'C4':("(가)",r"반지름의 비 $13:20$."),'C5':("(나)",r"$\overline{\mathrm O_1\mathrm O_2}$의 최솟값 $\frac{21}2$."),
  'C6':("(다)",r"$\mathrm P$가 하나뿐인 $k$ 중 $\frac{21}2$가 아닌 최솟값 $\frac{91}8$."),'C7':("묻는 것",r"넓이.")},
 [("사인법칙",[r"$\overline{\mathrm{AB}}=2R_1\sin\angle\mathrm{APB}$."]),("수직이등분선",[r"중심의 정사영은 현의 중점."])],
 [("의도",['C2']),("비",['C4']),("중심 거리",['C2']),("관계",['C2']),("비례",['C5']),("최솟값",['C5']),("한 점",['C6']),("답",['C7'])],
 [("$\\mathrm H$의 위치",'C5',[r"수선의 발이 변 위에 있어야 최솟값 존재."]),("$\\overline{\\mathrm{AP}}=13$",'C6',[r"$\mathrm P=\mathrm B$는 제외되어 한 점뿐."])],
 [("변형 · 비 $15:13$",[r"삼각형 $\mathrm{ABC}$의 변 $\mathrm{BC}$ 위를 움직이는 점 $\mathrm P$($\mathrm B$, $\mathrm C$ 제외)에 대하여 두 삼각형 $\mathrm{ABP}$, $\mathrm{APC}$의 외접원의 중심을 $\mathrm O_1$, $\mathrm O_2$라 하자. (가) 두 외접원의 반지름의 비는 $15:13$, (나) $\overline{\mathrm O_1\mathrm O_2}$의 최솟값은 $7$, (다) $\overline{\mathrm O_1\mathrm O_2}=k$인 $\mathrm P$가 오직 하나인 $k$ 중 $7$이 아닌 것의 최솟값은 $\frac{91}{12}$일 때, 삼각형 $\mathrm{ABC}$의 넓이를 구하시오."],84,r"$\overline{\mathrm{AB}}=15$, $\overline{\mathrm{AC}}=13$, 높이 $12$, $\overline{\mathrm{BC}}=14$.")],
 "두 외접원 = 사인법칙 비 + 중심 거리 ∝ $\\overline{\\mathrm{AP}}$.")
